interface.signature:
GET /api/memory/domains
Response: DomainListResponse {
  domains: List[DomainMetadata] = [
    {name: str, description: str, chunk_count: int}
  ]
}

GET /api/memory/tags
Response: TagsListResponse {
  tags: List[TagMetadata] = [
    {tag: str, description: str, count: int}
  ]
}

GET /api/cognitive-traces/{trace_id: UUID}
Response: CognitiveTraceResponse {
  trace_id: UUID,
  query: str,
  mode: str,
  severity: str,
  trace_data: dict (sanitized - no raw prompts/outputs),
  total_latency_ms: int,
  created_at: datetime
}

// Save profile
saveProfile(name: string, domains: string[], tags: string[]): void
// Load profile
loadProfile(name: string): {domains: string[], tags: string[]} | null
// Delete profile
deleteProfile(name: string): void
// List all profiles
listProfiles(): Array<{name: string, domains: string[], tags: string[], created: timestamp}>
